de caret, equivalente al # stratify=y de sklearn) idx_train &lt;- caret::createDataPartition(df[[TARGET]], p = 0.8, list = FALSE) train_df &lt;- df[idx_train, ] test_df &lt;- df[-idx_train, ] # Objetos que usa el resto del documento (chunk final `guardar-split`) X_train &lt;- train_df[, names(train_df) != TARGET] y_train &lt;- train_df[[TARGET]] X_test &lt;- test_df[, names(test_df) != TARGET] y_test &lt;- test_df[[TARGET]] cat(sprintf(&quot;Observaciones en train: %d (%.1f%%)
