(%.2f%%)&quot;, fmt_int(n), pct)), vjust = -0.3, fontface = &quot;bold&quot;, size = 3.6, color = PALETTE$downriver) + scale_fill_manual(values = TARGET_COLORS) + ylim(0, max(df_plot$n) * 1.22) + labs(title = &quot;Conteo de Empresas por Clase (Train)&quot;, x = NULL, y = NULL) + tema_eda + theme(axis.text.y = element_blank(), panel.grid = element_blank()) # 3. Ratio de desbalance, referenciado en la interpretación de la siguiente celda ratio_desbalance &lt;- conteo[[&quot;0&quot;]] / conteo[[&quot;1&quot;]] La variable objetivo presenta un fuerte desbalance de clases, ya que hay 5.279 empresas que no quiebran, equivalentes al 96,77 % del conjunto de entrenamiento, mientras que las que sí quiebran son 176 y representan el 3,23 %. Este desbalance deberá tenerse en cuenta durante el entrenamiento y la evaluación del modelo. 2.3.2 Variables numéricas 2.3.2.1 Estadísticas descriptivas unidad_indicador &lt;- function(variable) { # Devuelve la unidad/concepto con el que debe presentarse cada indicador. # No convierte el valor: solo define cómo debe interpretarse en el texto. nombre &lt;- str_to_lower(variable) contiene &lt;- function(terms) any(vapply(terms, function(t) grepl(t, nombre, fixed = TRUE), logical(1))) if (contiene(c(&quot;day&quot;, &quot;interval&quot;))) return(&quot;días&quot;) if (contiene(c(&quot;per share&quot;, &quot;eps&quot;, &quot;net value per share&quot;))) return(&quot;Yuan ¥/acción&quot;) if (contiene(&quot;per person&quot;)) return(&quot;Yuan ¥/persona&quot;) # En estas variables el valor del dataset se interpreta directamente # como una razón/ratio. No se expresa como &quot;veces&quot;. if (contiene(c(&quot;turnover&quot;, &quot;frequency&quot;))) return(&quot;ratio&quot;) if (contiene(c( &quot;current ratio&quot;, &quot;quick ratio&quot;, &quot;coverage ratio&quot;, &quot;financial leverage&quot;, &quot;borrowing dependency&quot;, &quot;total debt/total net worth&quot;, &quot;/equity&quot;, &quot;to equity&quot;, &quot;/net worth&quot;, &quot;to net worth&quot;, &quot;inventory and accounts receivable/net value&quot;, &quot;cash/current liability&quot;, &quot;quick assets/current liability&quot;, &quot;inventory/current liability&quot;, &quot;funds to liability&quot;, &quot;liability to current assets&quot;, &quot;equity to liability&quot;, &quot;cash flow to liability&quot;, &quot;total income/total expense&quot; ))) return(&quot;ratio&quot;) if (contiene(c( &quot;%&quot;, &quot;roa&quot;, &quot;rate&quot;, &quot;growth&quot;, &quot;margin&quot;, &quot;to assets&quot;, &quot;/assets&quot;, &quot;assets/&quot;, &quot;to sales&quot;, &quot;paid-in capital&quot;, &quot;net income to stockholder&quot;, &quot;cash flow to equity&quot;, &quot;interest expense ratio&quot; ))) return(&quot;porcentaje&quot;) &quot;ratio&quot; } formatear_valor &lt;- function(variable, valor, decimales = 4) { # Formatea un valor para las interpretaciones narrativas. Los indicadores # definidos como porcentaje se convierten de su escala decimal a porcentaje; # los ratios se mantienen en su escala original. if (is.na(valor)) return(&quot;NA&quot;) unidad &lt;- unidad_indicador(variable) if (unidad == &quot;porcentaje&quot;) return(sprintf(&quot;%.2f%%&quot;, valor * 100)) paste(sprintf(paste0(&quot;%.&quot;, decimales, &quot;f&quot;), valor), unidad) } # 1. Definición de la función para calcular las estadísticas descriptivas generar_estadisticas_univariadas &lt;- function(df, variables) { map_dfr(variables, function(var) { serie &lt;- df[[var]] serie &lt;- serie[!is.na(serie)] q &lt;- quantile(serie, c(0.25, 0.75), names = FALSE) tibble( Variable = var, N = length(serie), Media = mean(serie), DS = sd(serie), Curtosis = e1071::kurtosis(serie, type = 1), # Curtosis de Fisher (0 = normal) Mediana = median(serie), `Mínimo` = min(serie), `Máximo` = max(serie), Q1 = q[1], Q3 = q[2], IQR = q[2] - q[1] ) }) } # 2. Generar el resumen de las 93 variables numéricas sobre train_df df_stats_num &lt;- generar_estadisticas_univariadas(train_df, 