ón de &quot;, var, &quot; según Estado de Bancarrota (&quot;, TARGET, &quot;)&quot;), x = &quot;Estado de Bancarrota (0 = Solvente, 1 = Quiebra)&quot;, y = var) + tema_eda + theme(plot.title = element_text(size = 11), axis.text.x = element_text(face = &quot;bold&quot;, size = 9.5)) # 2. Guardar el gráfico como imagen embebida archivo &lt;- file.path(dir_imgs_biv, paste0(make.names(var), &quot;.png&quot;)) ggsave(archivo, p, width = 7.5, height = 4.2, dpi = 75) imagen_base64 &lt;- base64enc::base64encode(archivo) # 3. Métricas para la narrativa comparativa med_0 &lt;- median(grupo_0); med_1 &lt;- median(grupo_1) diff_mediana &lt;- med_1 - med_0 if (abs(diff_mediana) &lt; 0.01) { comparacion_mediana &lt;- &quot;medianas visualmente alineadas y un solapamiento alto en sus rangos intercuartílicos&quot; conclusion &lt;- paste0(&quot;la variable &lt;b style=&#39;color:&quot;, PALETTE$downriver, &quot;;&#39;&gt;&quot;, var, &quot;&lt;/b&gt; muestra un comportamiento similar entre ambos grupos sin una separación clara a simple vista.&quot;) } else if (diff_mediana &lt; 0) { comparacion_mediana &lt;- paste0(&quot;que el 50% de las empresas en quiebra se ubica en niveles inferiores de &lt;b style=&#39;color:&quot;, PALETTE$poinciana, &quot;;&#39;&gt;&quot;, var, &quot;&lt;/b&gt; (mediana cercana a &quot;, formatear_valor(var, med_1), &quot;) en comparación con el grupo solvente (mediana cercana a &quot;, formatear_valor(var, med_0), &quot;)&quot;) conclusion &lt;- paste0(&quot;los valores más bajos de &lt;b style=&#39;color:&quot;, PALETTE$poinciana, &quot;;&#39;&gt;&quot;, var, &quot;&lt;/b&gt; tienden a concentrarse en las empresas con riesgo de quiebra.&quot;) } else { comparacion_mediana &lt;- paste0(&quot;que el 50% de las empresas en quiebra presenta valores más elevados de &lt;b style=&#39;color:&quot;, PALETTE$flame, &quot;;&#39;&gt;&quot;, var, &quot;&lt;/b&gt; (mediana cercana a &quot;, formatear_valor(var, med_1), &quot;) frente al grupo sano (mediana cercana a &quot;, formatear_valor(var, med_0), &quot;)&quot;) conclusion &lt;- paste0(&quot;los valores más altos de &lt;b style=&#39;color:&quot;, PALETTE$flame, &quot;;&#39;&gt;&quot;, var, &quot;&lt;/b&gt; se aprecian con mayor frecuencia en el grupo con riesgo de quiebra.&quot;) } # 4. Bloque &lt;details&gt; plegable: título + imagen + interpretación detalles_numericas[k] &lt;- paste0( &#39;&lt;details class=&quot;var-details&quot;&gt;&lt;summary&gt;&#39;, var, &#39;&lt;/summary&gt;&lt;div style=&quot;padding:16px 18px;&quot;&gt;&#39;, &#39;&lt;div style=&quot;text-align:center;margin-bottom:14px;&quot;&gt;&lt;img src=&quot;data:image/png;base64,&#39;, imagen_base64, &#39;&quot; style=&quot;max-width:100%;height:auto;border-radius:4px;&quot;&gt;&lt;/div&gt;&#39;, &#39;&lt;p style=&quot;margin:0;color:&#39;, PALETTE$stone_blue, &#39;;font-size:13.5px;line-height:1.6;&quot;&gt;&#39;, &#39;El gráfico compara la distribución de &lt;b style=&quot;color:&#39;, PALETTE$downriver, &#39;;&quot;&gt;&#39;, var, &#39;&lt;/b&gt; entre empresas solventes (&lt;b style=&quot;color:&#39;, PALETTE$downriver, &#39;;&quot;&gt;0&lt;/b&gt;) y en quiebra (&lt;b style=&quot;color:&#39;, PALETTE$poinciana, &#39;;&quot;&gt;1&lt;/b&gt;). &#39;, &#39;Se observa &#39;, comparacion_mediana, &#39;. El rango central de los datos (IQR) muestra la dispersión interna de cada segmento, &#39;, &#39;evidenciándose la presencia de valores atípicos (&lt;i&gt;outliers&lt;/i&gt;) más allá de los bigotes. En resumen, &#39;, conclusion, &#39;&lt;/p&gt;&lt;/div&gt;&lt;/details&gt;&#39; ) if (k %% 15 == 0) invisible(gc(full = TRUE)) } # 5. Estilos del desplegable (una sola vez) + lista completa de las 93 variables html_estilo &lt;- paste0( &quot;&lt;style&gt;.var-details{margin:0 0 10px 0;border:1px solid #E1E4E9;border-radius:8px;overflow:hidden;background-color:#FFFFFF;}&quot;, &quot;.var-details summary{padding:12px 18px;cursor:pointer;font-size:14.5px;font-weight:600;color:&quot;, PALETTE$downriver, &quot;;background-color:&quot;, PALETTE$bg_card, &quot;;list-style:none;}&quot;, &quot;.var-details summary::-webkit-details-marker{display:none;}&quot;, &quot;.var-details summary::before{content:&#39;▶ &#39;;font-size:11px;color:&quot;, PALETTE$stone_blue, &quot;;}&quot;, &quot;.var-details[open] summary::before{content:&#39;▼ &#39;;}&lt;/style&gt;&quot; ) cat(html_estilo, &quot;&lt;div&gt;&quot;, paste(detalles_numericas, collapse = &quot;&quot;), &quot;&lt;/div&gt;

